using System.Collections.Generic; using UnityEngine; namespace HonourWar { public sealed class HonourWarWorldDirector:MonoBehaviour { public readonly List<HonourWarMonster> Monsters=new(); public void BuildProceduralWorld(){for(int i=0;i<24;i++){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name=$"TownBlock_{i+1:00}";go.transform.position=new Vector3((i%6)*8-20,1,(i/6)*8-12);go.transform.localScale=new Vector3(5,2,5);} for(int i=0;i<32;i++){var go=new GameObject($"Monster_{i+1:000}");go.transform.position=new Vector3((i%8)*7-24,1,(i/8)*7+18);var m=go.AddComponent<HonourWarMonster>();m.Initialize($"MON_{i+1:000}",$"Honour Monster {i+1}",EHonourWarMonsterSpecies.Poring,Mathf.Clamp(10+i*5,1,250));Monsters.Add(m);}} } }